-- 2330_keep_photo_location_setting.sql
--
-- A140 (RRR-204, trace S13-10; Section 13 Media: "Photos compressed to 2048 px; EXIF location kept only if the org
-- enables it"). Compass resizes every field photo and re-encodes it as JPEG, which drops the camera's EXIF. With
-- media.keep_photo_location on, Compass writes the GPS tags the camera recorded back into the resized file
-- (apps/compass/src/runtime/media.ts); off, the default, the uploaded photo carries no location. The org sets it in
-- Settings, Data and Privacy, with data.classification.write.
-- Statement generated by `pnpm --filter @xos/schemas settings:sql a140`.

select private.define_setting('media.keep_photo_location', 'Boolean', 'data.classification.write', array['organization'], false, p_default_boolean => false);
